function update(){eff=Number($('#eff').value);$('#throughput').innerHTML=eff+'<span>%</span>';$('#effvalue').textContent=eff+'%';$('#meter').style.width=eff+'%';$('#orders').innerHTML=Math.round(3420*eff/94).toLocaleString()+'<small>/hr</small>';$('#bottlenecks').textContent=eff<60?Math.ceil((60-eff)/10):0;$('#active').innerHTML=(eff<60?25:38)+' <small>/ 40</small>';$('#mode').textContent=eff<60?'● CONGESTED':eff>90?'● PEAK EFFICIENCY':'● STEADY FLOW';$('#mode').style.color=eff<60?'#ffad64':'#42e4c1';$('#dockstatus').textContent=eff<60?'Delayed · Backlog detected':'Unloading · Optimal';$('#sortstatus').textContent=Math.min(100,eff+4)+'% flow efficiency';$('#trend').textContent=eff<60?'↘ Backlog at packing stations':eff>90?'↗ Operating at peak capacity':'→ Balanced distribution';$('#zonecount').textContent=eff<60?'Action required':'All systems healthy';$('.panelheading .live').textContent=eff<60?'● DELAYED':'● OPTIMAL';$('#eventtext').textContent=eff<60?'AGV queue at junction B · Dispatch delayed':'AGV–028 → Dispatch lane · Route clear'}
