function setZoom(z){zoom=Math.min(2.5,Math.max(.5,z))}$('#zoomIn').onclick=()=>setZoom(zoom*1.15);$('#zoomOut').onclick=()=>setZoom(zoom/1.15);$('#reset').onclick=()=>{zoom=1;angle=-.55;pan={x:0,y:0}};canvas.onwheel=e=>{e.preventDefault();setZoom(zoom*Math.exp(-e.deltaY*.001))};canvas.oncontextmenu=e=>e.preventDefault();let drag=null;canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,button:e.button};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;angle+=(e.clientX-drag.x)*.006;pan.y+=(e.clientY-drag.y)*.35;drag.x=e.clientX;drag.y=e.clientY};canvas.onpointerup=e=>{if(drag&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5){const hit=hitZones.find(p=>Math.hypot(p.x-e.clientX,p.y-e.clientY)<45);if(hit)selectBay(hit.bay)}drag=null};canvas.onpointercancel=()=>drag=null;function clock(){ $('#clock').textContent=new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Kolkata'})+' IST'}clock();setInterval(clock,1000);

